#!/usr/bin/env python3
"""Checks that the launcher-icon colours generated by brand_logo.py / gen_app_icons.py match what the app draws.

  python3 scripts/check_logo_palette.py

It contains a second, independent line-by-line port of app/.../splash/LogoPalette.kt (float32 like the JVM) and of the tile
maths in BrandTile.kt / Color.kt, reads the accent colours straight from Accent.kt, and compares them with the Python
generator for every accent x (dark, light) x gradient stop.  Exit code 1 on any difference (> 1/255 on a channel).
"""
import os, re, sys
import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import brand_logo as BL
import gen_app_icons as G

F = np.float32
ROOT = BL.ROOT
read = lambda p: open(os.path.join(ROOT, p), encoding='utf-8').read()

# ---- Accent.kt (parsed again here, on purpose, in a different way)
def parse_accents():
    src = read('designsystem/src/main/java/com/frameout/designsystem/theme/Accent.kt')
    out = {}
    for m in re.finditer(r'val (\w+) = palette\((.*?)\n    \)', src, re.S):
        body = m.group(2)
        key = re.search(r'key = "(\w+)"', body).group(1)
        arr = lambda name: [int(x, 16) for x in re.findall(r'0xFF(\w{6})', re.search(r'\b' + name + r' = longArrayOf\(([^)]*)\)', body).group(1))]
        out[key] = dict(stops=arr('stops'), light=arr('light'), neutral='neutral = true' in body)
    return out

def rgb(v): return np.array([(v >> 16) & 255, (v >> 8) & 255, v & 255], dtype=F)

def mixf(a, b, t): return (a * F(1 - t) + b * F(t)).astype(F)
def lumf(c): return F(0.2126) * c[0] + F(0.7152) * c[1] + F(0.0722) * c[2]
def chromaf(c): return (max(c) - min(c)) / F(255)
def huef(c):
    r, g, b = c[0] / F(255), c[1] / F(255), c[2] / F(255)
    mx = max(r, g, b); d = mx - min(r, g, b)
    if d == 0: return F(0)
    h = ((g - b) / d) % F(6) if mx == r else (b - r) / d + F(2) if mx == g else (r - g) / d + F(4)
    return (h * F(60) + F(360)) % F(360)

WHITE = np.full(3, 255, F); BLACK = np.zeros(3, F)
O_RAMP = [np.array(v, F) for v in ([1, 246, 253], [42, 68, 251], [119, 37, 251], [208, 42, 252])]
O_POP = [np.array(v, F) for v in ([252, 168, 75], [251, 86, 134])]
O_RAMP_H = [huef(c) for c in O_RAMP]; O_POP_H0 = huef(O_POP[0]); O_POP_H1 = huef(O_POP[1]) - F(360)

class KotlinPalette:
    def __init__(self, key, acc, on_light):
        self.neutral, self.on_light = acc['neutral'], on_light
        self.ink = mixf(rgb(acc['light'][0]), BLACK, .55)
        if key == 'indigo': self.ramp, self.pop = O_RAMP, O_POP
        else:
            a, b, c = (rgb(v) for v in acc['stops']); b2 = mixf(b, WHITE, .18)
            self.ramp = [mixf(c, WHITE, .10), a, b, b2]; self.pop = [mixf(c, WHITE, .30), mixf(b2, WHITE, .25)]

    def color(self, argb):
        x = np.array([(argb >> 16) & 255, (argb >> 8) & 255, argb & 255], F)
        r = self.remap(x); return r
    def remap(self, x):
        if chromaf(x) <= F(.08): return mixf(x, self.ink, .88) if (self.on_light and lumf(x) > 140) else x
        h = huef(x)
        if 168 <= h <= 300:
            hh = min(max(h, O_RAMP_H[0]), O_RAMP_H[3]); i = 0
            while i < 2 and hh > O_RAMP_H[i + 1]: i += 1
            u = (hh - O_RAMP_H[i]) / (O_RAMP_H[i + 1] - O_RAMP_H[i])
            oi = mixf(O_RAMP[i], O_RAMP[i + 1], u); ni = mixf(self.ramp[i], self.ramp[i + 1], u)
        else:
            if h > 180: h -= F(360)
            u = min(max((O_POP_H0 - h) / (O_POP_H0 - O_POP_H1), 0), 1)
            oi = mixf(O_POP[0], O_POP[1], u); ni = mixf(self.pop[0], self.pop[1], u)
        out = np.clip(ni + (x - oi), 0, 255).astype(F)
        if self.on_light: out = mixf(out, self.ink, float(min(max((lumf(out) - 110) / 145, 0), 1)) * .5)
        if self.neutral: g = lumf(out); out = np.array([g, g, g], F)
        return out

def main():
    acc = parse_accents(); bad = 0; n = 0
    assert set(acc) == set(BL.ACCENTS), (set(acc) ^ set(BL.ACCENTS))
    for key in acc:
        for variant in ('dark', 'light'):
            kp = KotlinPalette(key, acc[key], variant == 'light')
            for layer in BL.LAYERS:
                for (o, c), (o2, hexc, a2) in zip(layer['stops'], BL.layer_stops(layer, key, variant)):
                    rgb0, alpha = BL.parse_color(c)
                    want = kp.color((int(round(alpha * 255)) << 24) | (int(rgb0[0]) << 16) | (int(rgb0[1]) << 8) | int(rgb0[2]))
                    got = np.array(BL.hx(hexc), float); n += 1
                    if np.abs(np.round(want) - got).max() > 1:
                        bad += 1; print('MISMATCH', key, variant, layer['name'], o, want.round(1), got)
    print(f'logo colours: {n} stops checked, {bad} mismatches')
    # ---- tiles: dark = BrandTile.drawTileBody gradient, light = lightColorScheme().background, amoled = black
    ink = np.array([5, 6, 15], float)
    bad_t = 0
    for key, a in acc.items():
        A = rgb(a['stops'][0]).astype(float); B = rgb(a['stops'][1]).astype(float)
        t0 = ink * .8 + B * .2; t1 = ink * .92 + A * .08
        gt0, gt1 = (np.array(G.hx(v), float) for v in G.tile_stops(key))
        if np.abs(t0 - gt0).max() > 1 or np.abs(t1 - gt1).max() > 1: bad_t += 1; print('DARK TILE', key, t0, gt0, t1, gt1)
        lb = np.array([0xE6, 0xE8, 0xF1], float) * .95 + A * .05 if not a['neutral'] else np.array([255, 255, 255.])
        if np.abs(lb - np.array(G.hx(G.LIGHT_TILE[key]), float)).max() > 1: bad_t += 1; print('LIGHT TILE', key, lb, G.LIGHT_TILE[key])
    print(f'tiles: {bad_t} mismatches')
    sys.exit(1 if bad or bad_t else 0)

if __name__ == '__main__':
    main()
